{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.yokingma/one-search-mcp",
  "description": "Web search, URL discovery, scrape & extract with agent-browser, SearXNG, Tavily, DuckDuckGo, Bing & more",
  "repository": {
    "url": "https://github.com/yokingma/one-search-mcp",
    "source": "github"
  },
  "version": "1.2.3",
  "packages": [
    {
      "registryType": "npm",
      "identifier": "one-search-mcp",
      "version": "1.2.3",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "description": "Search provider to use (searxng, duckduckgo, bing, tavily, google, zhipu, exa, bocha, local)",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "SEARCH_PROVIDER"
        },
        {
          "description": "API URL for SearXNG (required if using searxng provider), or Google Custom Search Engine ID for google",
          "isRequired": false,
          "format": "string",
          "isSecret": false,
          "name": "SEARCH_API_URL"
        },
        {
          "description": "API key for search provider (required for tavily, bing, google, zhipu, exa, bocha)",
          "isRequired": false,
          "format": "string",
          "isSecret": true,
          "name": "SEARCH_API_KEY"
        },
        {
          "description": "Allow browser-backed tools to access private, loopback, and link-local network targets when set to true",
          "isRequired": false,
          "format": "boolean",
          "isSecret": false,
          "name": "ALLOW_PRIVATE_NETWORK"
        }
      ]
    }
  ]
}
